            case 'list-video':
                // No exact Pencil export for this one - card header icon for
                // the new Playlist Items (track list) card, same muted-grey
                // fill and shape language as 'header'/'items' just above
                // (plain <rect>/<path> primitives, not a traced SVG path):
                // a play-badge box (this card's rows are tracks) plus three
                // short bars standing in for the row list beside it.
                return <<<'SVG'
<svg
                  viewBox="0 0 14 14"
                  preserveAspectRatio="xMidYMid meet"
                  xmlns="http://www.w3.org/2000/svg"
                  class="lpl-box-border lpl-w-[16px] lpl-shrink-0 lpl-h-[16px]"
