SVG;
            case 'grip-vertical':
                // Drag handle for Playlist Items rows - six dots, currentColor
                // so it inherits whatever text color its wrapping element
                // sets (same currentColor approach as 'x'/'circle-plus'
                // above), since the handle needs to dim/highlight with row
                // hover state rather than carrying a fixed fill.
                return <<<'SVG'
<svg
                  viewBox="0 0 14 14"
                  preserveAspectRatio="xMidYMid meet"
                  xmlns="http://www.w3.org/2000/svg"
                  class="lpl-box-border lpl-w-[14px] lpl-shrink-0 lpl-h-[14px]"
